    @staticmethod
    def merge_all(lists):
        """
        Merge multiple lists while trying to keep the relative order of the
        elements. Warn if any two lists have the same elements in a different
        relative order.

        Uses topological sort to correctly handle merging 3+ lists without
        introducing false ordering constraints from intermediate pairwise
        merges.
        """
        # Filter out empty lists.
        non_empty = [lst for lst in lists if lst]
        if not non_empty:
            return []
        if len(non_empty) == 1:
            return list(non_empty[0])

        # Collect all unique items preserving first-seen order.
        all_items = []
        seen = set()
        for lst in non_empty:
            for item in lst:
                if item not in seen:
                    all_items.append(item)
                    seen.add(item)

        # Build adjacency list and in-degree count for topological sort.
        graph = {item: set() for item in all_items}
        in_degree = {item: 0 for item in all_items}

        for lst in non_empty:
            for i in range(len(lst) - 1):
                if lst[i + 1] not in graph[lst[i]]:
                    graph[lst[i]].add(lst[i + 1])
                    in_degree[lst[i + 1]] += 1

        # Check for conflicts: pairs of items that appear in opposite orders
        # across different input lists.
        warned = set()
        for i, lst1 in enumerate(non_empty):
            for j, lst2 in enumerate(non_empty):
                if i >= j:
                    continue
                positions1 = {item: pos for pos, item in enumerate(lst1)}
                for pos2_a, item_a in enumerate(lst2):
                    if item_a not in positions1:
                        continue
                    for pos2_b, item_b in enumerate(lst2):
                        if pos2_b <= pos2_a:
                            continue
                        if item_b not in positions1:
                            continue
                        # In lst2, item_a comes before item_b.
                        # Check if in lst1, item_b comes before item_a.
                        if positions1[item_b] < positions1[item_a]:
                            pair = (min(item_a, item_b), max(item_a, item_b))
                            if pair not in warned:
                                warned.add(pair)
                                warnings.warn(
                                    'Detected duplicate Media files in an opposite order:\n'
                                    '%s\n%s' % (item_b, item_a),
                                    MediaOrderConflictWarning,
                                )

        # Kahn's algorithm for topological sort.
        queue = [item for item in all_items if in_degree[item] == 0]
        result = []
        while queue:
            # Sort queue to pick the item that appeared earliest across all
            # lists, ensuring stable/deterministic results.
            def sort_key(item):
                for idx, lst in enumerate(non_empty):
                    if item in lst:
                        return (idx, lst.index(item))
                return (len(non_empty), 0)
            queue.sort(key=sort_key)
            node = queue.pop(0)
            result.append(node)
            for neighbor in graph[node]:
                in_degree[neighbor] -= 1
                if in_degree[neighbor] == 0:
                    queue.append(neighbor)

        return result
