    def _merge_media_lists(lists):
        """
        Merge multiple media lists using topological sort to preserve the
        relative order of elements from all input lists. Warn if there is a
        genuine ordering conflict (cycle in the dependency graph).

        For static assets it can be important to have them included in the DOM
        in a certain order. In JavaScript you may not be able to reference a
        global or in CSS you might want to override a style.
        """
        if not lists:
            return []

        # Build adjacency list and track insertion order for determinism.
        graph = {}
        order = []
        seen = set()

        for lst in lists:
            for item in lst:
                if item not in seen:
                    seen.add(item)
                    order.append(item)
                    graph[item] = set()

        for lst in lists:
            for i in range(len(lst) - 1):
                graph[lst[i]].add(lst[i + 1])

        # DFS-based topological sort.
        WHITE, GRAY, BLACK = 0, 1, 2
        color = {node: WHITE for node in order}
        result = []
        cycle_nodes = set()

        def dfs(node):
            color[node] = GRAY
            # Sort neighbors by their first appearance order for determinism.
            for neighbor in sorted(graph[node], key=order.index):
                if color[neighbor] == GRAY:
                    # Back edge found — genuine cycle.
                    cycle_nodes.add(node)
                    cycle_nodes.add(neighbor)
                elif color[neighbor] == WHITE:
                    dfs(neighbor)
            color[node] = BLACK
            result.append(node)

        for node in order:
            if color[node] == WHITE:
                dfs(node)

        result.reverse()

        if cycle_nodes:
            cycle_list = sorted(cycle_nodes, key=order.index)
            warnings.warn(
                'Detected duplicate Media files in an opposite order:\n'
                '%s\n%s' % (cycle_list[0], cycle_list[1] if len(cycle_list) > 1 else cycle_list[0]),
                MediaOrderConflictWarning,
            )

        return result

